"""Google sign-in (generated by Shikshya, P1b.6 R2). The start view keeps the state and the PKCE verifier in a short
signed httpOnly cookie; the callback checks the state, swaps the code and verifies the id token (google_auth/flow.py)
and accepts only a verified email. The browser gets a signed code, valid for two minutes, after the last '#', which no
server or log sees; the page /auth/google/done swaps it once for a sign-in token (a knox token, like a password
sign-in)."""
import logging
import secrets

from django.conf import settings
from django.contrib.auth import get_user_model
from django.core import signing
from django.db import transaction
from django.http import HttpResponseRedirect
from django.utils import timezone
from django.utils.crypto import constant_time_compare, salted_hmac
from knox.models import AuthToken
from rest_framework import status
from rest_framework.permissions import AllowAny
from rest_framework.response import Response
from rest_framework.throttling import ScopedRateThrottle
from rest_framework.views import APIView

from api.serializers_auth import UserSerializer

from . import flow
from .models import GoogleIdentity

logger = logging.getLogger(__name__)
COOKIE = "google_oauth"
COOKIE_PATH = "/api/auth/google/"
COOKIE_TTL_S = 600
HANDOFF_TTL_S = 120
STATE_SALT = "google_auth.state"
HANDOFF_SALT = "google_auth.handoff"
ROLE_FIELD = 'role'
STAFF_ROLES = ('doctor', 'receptionist')
BAD_CODE = {"detail": "The sign-in code is invalid or expired."}


def _finish(fragment: str) -> HttpResponseRedirect:
    """Back to the app's page /auth/google/done with the outcome after the last '#'."""
    base = (getattr(settings, "FRONTEND_URL", "") or settings.PUBLIC_URL).rstrip("/")
    response = HttpResponseRedirect(base + "/#/auth/google/done#" + fragment)
    response.delete_cookie(COOKIE, path=COOKIE_PATH)
    return response


def _is_staff(user) -> bool:
    return bool(user.is_staff or user.is_superuser or (ROLE_FIELD and getattr(user, ROLE_FIELD, None) in STAFF_ROLES))


def _handoff_stamp(user) -> str:
    """Changes when the code is swapped (last_login) or the password changes, so a code works once."""
    return salted_hmac(HANDOFF_SALT, "%s|%s|%s" % (user.pk, user.password, user.last_login)).hexdigest()


def _free_username(User, email: str) -> str:
    base = "".join(c for c in email.split("@")[0] if c.isalnum() or c in "_.-")[:30] or "user"
    for n in range(1, 51):
        name = base if n == 1 else "%s%d" % (base, n)
        if not User.objects.filter(**{User.USERNAME_FIELD: name}).exists():
            return name
    return "%s-%s" % (base, secrets.token_hex(4))


def _new_user(User, email: str, first: str, last: str):
    names = {f.name for f in User._meta.get_fields()}
    extra = {k: v[:150] for k, v in (("first_name", first), ("last_name", last)) if k in names}
    if User.USERNAME_FIELD == "email":
        return User.objects.create_user(email=email, password=None, **extra)
    return User.objects.create_user(_free_username(User, email), email=email, password=None, **extra)


def _google_user(sub: str, email: str, first: str, last: str):
    """(user, refusal): the account linked to this Google identity; else the one account with its verified email,
    linked now; else a new account. Sign-up never verified an email, so whoever set the password of the account found
    by email may not own the address: linking replaces that password and ends every sign-in. A staff account, an email
    on two accounts and an account linked to another Google identity are refused."""
    User = get_user_model()
    with transaction.atomic():
        link = GoogleIdentity.objects.select_related("user").filter(sub=sub).first()
        if link is not None:
            return (link.user, "") if link.user.is_active else (None, "inactive")
        matches = list(User.objects.select_for_update().filter(email__iexact=email).order_by("pk")[:2])
        if len(matches) > 1:
            return None, "conflict"
        if matches:
            user = matches[0]
            if not user.is_active:
                return None, "inactive"
            if _is_staff(user):
                return None, "staff"
            if GoogleIdentity.objects.filter(user=user).exists():
                return None, "conflict"
            user.set_unusable_password()
            user.save(update_fields=["password"])
            AuthToken.objects.filter(user=user).delete()
        else:
            user = _new_user(User, email, first, last)
        GoogleIdentity.objects.create(user=user, sub=sub)
        return user, ""


class GoogleStatusView(APIView):
    """GET /api/auth/google/status/: whether Google sign-in is set up (the button reads it)."""
    authentication_classes = []
    permission_classes = [AllowAny]

    def get(self, request):
        return Response({"configured": flow.configured()})


class GoogleStartView(APIView):
    """GET /api/auth/google/: send the browser to Google."""
    authentication_classes = []
    permission_classes = [AllowAny]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "auth"

    def get(self, request):
        if not flow.configured():
            return _finish("error=not_configured")
        state = secrets.token_urlsafe(24)
        verifier, challenge = flow.new_pkce()
        response = HttpResponseRedirect(flow.auth_url(state, challenge))
        response.set_cookie(COOKIE, signing.dumps({"state": state, "verifier": verifier}, salt=STATE_SALT),
                            max_age=COOKIE_TTL_S, path=COOKIE_PATH, secure=not settings.DEBUG, httponly=True,
                            samesite="Lax")
        return response


class GoogleCallbackView(APIView):
    """GET /api/auth/google/callback/: Google sends the browser back here with a code."""
    authentication_classes = []
    permission_classes = [AllowAny]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "auth"

    def get(self, request):
        if not flow.configured():
            return _finish("error=not_configured")
        if request.GET.get("error"):
            return _finish("error=denied")
        try:
            saved = signing.loads(request.COOKIES.get(COOKIE, ""), salt=STATE_SALT, max_age=COOKIE_TTL_S)
        except signing.BadSignature:
            return _finish("error=expired")
        state, code = request.GET.get("state", ""), request.GET.get("code", "")
        if not state or not code or not constant_time_compare(state, str(saved.get("state", ""))):
            return _finish("error=state")
        try:
            claims = flow.verified_claims(code, str(saved.get("verifier", "")))
        except Exception as exc:
            logger.warning("google sign-in failed: %s", type(exc).__name__)
            return _finish("error=google")
        email = str(claims.get("email") or "")
        if not claims.get("sub") or not email or claims.get("email_verified") is not True:
            return _finish("error=unverified")
        try:
            user, refusal = _google_user(str(claims["sub"]), email, str(claims.get("given_name") or ""),
                                         str(claims.get("family_name") or ""))
        except Exception as exc:
            logger.warning("google sign-in failed: %s", type(exc).__name__)
            return _finish("error=google")
        if user is None:
            return _finish("error=" + refusal)
        logger.info("google sign-in user=%s", user.pk)
        return _finish("code=" + signing.dumps({"u": user.pk, "s": _handoff_stamp(user)}, salt=HANDOFF_SALT))


class GoogleExchangeView(APIView):
    """POST /api/auth/google/exchange/ {"code"}: the code from /auth/google/done, once, for a sign-in token."""
    authentication_classes = []
    permission_classes = [AllowAny]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "auth"

    def post(self, request):
        code = request.data.get("code", "") if hasattr(request.data, "get") else ""
        try:
            data = signing.loads(str(code), salt=HANDOFF_SALT, max_age=HANDOFF_TTL_S)
        except signing.BadSignature:
            return Response(BAD_CODE, status=status.HTTP_400_BAD_REQUEST)
        User = get_user_model()
        with transaction.atomic():
            user = User.objects.select_for_update().filter(pk=data.get("u")).first()
            if user is None or not user.is_active or not constant_time_compare(_handoff_stamp(user),
                                                                               str(data.get("s", ""))):
                return Response(BAD_CODE, status=status.HTTP_400_BAD_REQUEST)
            user.last_login = timezone.now()
            user.save(update_fields=["last_login"])
        AuthToken.objects.filter(user=user, expiry__lt=timezone.now()).delete()
        _, token = AuthToken.objects.create(user)
        return Response({"token": token, "user": UserSerializer(user).data})
